  const newScale = this.currentScale + 0.2;
  this.renderPage(this.currentDocumentIndex, this.currentPage[this.currentDocumentIndex], newScale);
},

zoomOut() {
  const newScale = this.currentScale - 0.2;
  if (newScale > 0.1) {
    this.renderPage(this.currentDocumentIndex, this.currentPage[this.currentDocumentIndex], newScale);
  }
},

prevPage() {
  const fileId = this.currentDocumentIndex;
  if (this.currentPage[fileId] > 1 && !this.isRendering) {

    this.currentPage[fileId] = this.currentPage[fileId] - 1; 
    this.renderPage(fileId, this.currentPage[fileId]);
  }
},

nextPage() {
  const fileId = this.currentDocumentIndex;
  if (this.currentPage[fileId] < this.pdfPages[fileId].length && !this.isRendering) {
    this.currentPage[fileId] = this.currentPage[fileId] + 1; 
    this.renderPage(fileId, this.currentPage[fileId]);
  }
},

addSignatureField(fileId) {
  const currentPageNumber = this.currentPage[fileId];

  if (!this.signatureCounters[fileId]) {
    this.signatureCounters[fileId] = 1;
  }

  let availableId = this.availableIdsPerDoc[fileId] && this.availableIdsPerDoc[fileId].length > 0
    ? this.availableIdsPerDoc[fileId].shift()  
    : this.signatureCounters[fileId]++;  

  const uniqueId = `${fileId}-${uuidv4()}`;

  const newField = {
    id: uniqueId,
    instanceId: uniqueId,
    name: `[$FIRMA${availableId}]`,
    type: 'signature',
    top: 20,
    left: 50,
    width: 200,
    height: 100,
    pageNumber: currentPageNumber,
    fileId: fileId,
    includeFullName: true,
    includeDocumentInfo: true,
  };

  this.fields.push(newField);
  this.$emit('update-fields', this.fields, fileId);
},

addQrField(fileId) {
  if (this.hasQrField) return;

  const currentPageNumber = this.currentPage[fileId];
  const uniqueId = `${fileId}-${uuidv4()}`;

  const newField = {
    id: uniqueId,
    instanceId: uniqueId,
    name: 'Código QR',
    type: 'qr',
    top: 50,
    left: 50,
    width: 100,
    height: 100,
    pageNumber: currentPageNumber,
    fileId: fileId,
  };

  this.fields.push(newField);

