goToStep(step) {
    this.step = step;
    this.menu = false;
},

saveFiles(payload) {
    if (payload && payload.files && payload.files.length) {
        this.files = payload.files;
        this.uploadReady = true;
        this.name = payload.name;
        this.documentName = payload.files.map(f => f.name).join(', ');
    } else {

        this.uploadReady = false;

        this.files = [];
        this.name = '';
        this.documentName = '';
    }
},

updateViewerFields(fields, fileId) {
    this.viewerFields = this.viewerFields.filter(f => f.fileId !== fileId);

    const updatedFields = fields.map(field => ({
        ...field,
        fileId: fileId,
    }));

    updatedFields.forEach(newField => {
        const exists = this.viewerFields.some(existingField =>
            existingField.name === newField.name &&
            existingField.fileId === newField.fileId &&
            existingField.pageNumber === newField.pageNumber
        );

        if (!exists) {
            this.viewerFields.push(newField);
        }
    });

},

saveAndGoToStep5() {
    if (this.$refs.expires_in_days.validate()) {
        const fieldsByName = {};

        this.viewerFields.forEach(field => {
            if (field.type === 'qr') return;

            if (!fieldsByName[field.name]) {
                fieldsByName[field.name] = {
                    id: field.id,
                    name: field.name,
                    nombres: '',
                    apellidos: '',
                    correo: '',
                    celular: '',
                    celular_code: 57,
                    tipo_documento: '',
                    documento: '',
                    hasData: false,
                    isAutocompleteEnabled: false,
                    locations: []
                };
            }

            fieldsByName[field.name].locations.push({
                documentId: field.fileId,
                pageNumber: field.pageNumber
            });
        });

        this.formFields = Object.values(fieldsByName);

        if (this.additionalOptions.length > 0) {
            this.goToStep(6);
        } else {
            this.goToStep(5);
        }

