async handleSubmit() {
    try {

        const { isConfirmed } = await Swal.fire({
            title: "¿Desea añadir destinatarios para que reciban una copia de los documentos firmados?",
            icon: "question",
            showCancelButton: true,
            confirmButtonText: "Sí",
            cancelButtonText: "No",
        });

        if (isConfirmed) {
            this.showAdditionalStep = true;
            this.goToStep(this.getRecipientStep);
        } else {


            await this.sendRequest();
        }

    } catch (error) {
        console.error(error);
    }

},

async sendRequest() {

    try {

        this.isLoading = true;
        this.combineDateTime();

        const formData = new FormData();

        this.files.forEach((file, index) => {
            formData.append('files', file);
            formData.append('fileOrder[]', index);
        });

        const groupedFields = {};
        const groupedQrFields = {};

        this.viewerFields.forEach(field => {
            if (field.type === 'qr') {
                if (!groupedQrFields[field.fileId]) {
                    groupedQrFields[field.fileId] = [];
                }
                groupedQrFields[field.fileId].push(field);
            } else {
                if (!groupedFields[field.fileId]) {
                    groupedFields[field.fileId] = [];
                }
                groupedFields[field.fileId].push(field);
            }
        });

        const localDateTime = new Date(`${this.sendDate}T${this.sendTime}:00`);
        const sendAt = localDateTime.toISOString();

        formData.append('name', this.name);
        formData.append('documentName', this.documentName);
        formData.append('signer_fields', JSON.stringify(this.formFields));
        formData.append('fields', JSON.stringify(groupedFields));
        formData.append('send_date', sendAt);
        formData.append('qr_fields', JSON.stringify(groupedQrFields));

