317→    },
318→
319→    includeAllData: {
320→      get() {
321→        if (!this.editingField) return false;
322→        return this.editingField.includeFullName && this.editingField.includeDocumentInfo;
323→      },
324→
325→      set(newValue) {
326→        if (this.editingField) {
327→          this.editingField.includeFullName = newValue;
328→          this.editingField.includeDocumentInfo = newValue;
329→        }
330→      }
331→    }
332→  },
333→  watch: {
334→    files: {
335→      immediate: true,
336→      handler(newFiles) {
337→        if (newFiles && newFiles.length > 0) {
338→          this.loadPDFs(newFiles);
339→        }
