341→      
342→    },
343→
344→    'editingField.includeFullName'(newValue) {
345→      console.log('includeDocumentInfo changed to:', newValue);
346→      if (newValue === true) {
347→        this.enforceMinDataSize();
348→      }
349→    },
350→
351→    'editingField.includeDocumentInfo'(newValue) {
352→      if (newValue === true) {
353→        this.enforceMinDataSize();
354→      }
355→    },
356→
357→    fields: {
358→      deep: true,
359→      handler(newFields) {
360→        const groupedFields = {};
361→
362→        newFields.forEach(field => {
363→          if (field.fileId !== undefined && field.fileId !== null) {
364→            if (!groupedFields[field.fileId]) {
365→              groupedFields[field.fileId] = [];
366→            }
367→            groupedFields[field.fileId].push(field);
368→          }
369→        });
370→
371→        Object.keys(groupedFields).forEach(fileId => {
372→          this.$emit('update-fields', groupedFields[fileId], parseInt(fileId));
373→        });
374→      },
375→    },
376→
377→
378→  },
379→
380→  created() {
381→   
382→  },
383→  methods: {
384→
385→    async loadPDFs(files) {
386→      this.loadingPDFs = true;
387→      this.pdfs = [];
388→      this.pdfPages = {};
389→      this.scales = {};
390→      this.signatureCounters = {};
391→
392→      for await (const [index, file] of files.entries()) {
393→        try {
394→          const fileReader = new FileReader();
395→
396→          const pdfData = await new Promise((resolve) => {
397→            fileReader.onload = (e) => resolve(new Uint8Array(e.target.result));
398→            fileReader.readAsArrayBuffer(file);
399→          });
400→
401→          const loadingTask = pdfjsLib.getDocument({ data: pdfData });
402→          const pdf = await loadingTask.promise;
403→
404→          this.pdfs.push(markRaw(pdf));
405→
406→          this.pdfPages[index] = Array.from({ length: pdf.numPages }, (_, i) => i + 1);
407→          this.currentPage[index] = 1;
408→          this.signatureCounters[index] = 1;
409→
410→          if (index === this.currentDocumentIndex) {
411→            this.$nextTick(() => {
412→              this.renderPage(index, this.currentPage[index]);
413→            });
414→          }
415→
416→        } catch (error) {
417→          console.error('Error loading PDF:', error);
418→        }
419→      }
420→        this.loadingPDFs = false;
421→    },
422→
423→    async renderPage(fileId, pageNum,  scaleOverride = null) {
424→      try {
425→        if (this.isRendering) {
426→          try {
427→            await this.renderingTask.cancel();
428→          } catch (cancelErr) {
429→            console.warn('No se pudo cancelar render anterior:', cancelErr);
430→          }
431→        }
432→
433→        this.isRendering = true;
434→        this.renderingTask = null;
435→
436→        const canvas = this.$refs.pdfCanvas;
437→        const container = this.$refs.pdfContainer;
438→        const pdfDoc = this.pdfs[fileId];
439→
440→        if (!pdfDoc || typeof pdfDoc.getPage !== 'function') {
441→          throw new Error('Documento PDF no válido o no cargado');
442→        }
443→
444→        const page = await pdfDoc.getPage(pageNum);
445→        const originalViewport = page.getViewport({ scale: 1 });
446→
447→        this.originalPdfWidth = originalViewport.width;
448→        this.originalPdfHeight = originalViewport.height;
449→
450→        const baseScale = scaleOverride ?? this.currentScale ?? 1;
451→        const containerHeight = container.clientHeight - 32;
452→        const computedScale = baseScale || (containerHeight / originalViewport.height);
453→
454→        this.currentScale = computedScale;
455→
456→        const dpr = window.devicePixelRatio || 1;
457→        const viewport = page.getViewport({ scale: computedScale * dpr });
458→
459→        canvas.width = viewport.width;
460→        canvas.height = viewport.height;
461→        canvas.style.width = `${viewport.width / dpr}px`;
462→        canvas.style.height = `${viewport.height / dpr}px`;
463→
464→        const context = canvas.getContext('2d');
465→        const renderTask = page.render({ canvasContext: context, viewport });
466→        this.renderingTask = renderTask;
467→
468→        await renderTask.promise;
469→
470→        this.renderingTask = null;
471→
472→        this.$nextTick(() => {
473→          const rect = canvas.getBoundingClientRect();
474→          this.pdfCanvasWidth = rect.width;
475→          this.pdfCanvasHeight = rect.height;
476→        });
477→
478→      } catch (err) {
479→        console.error('Error al renderizar página:', err);
480→      }
481→
482→      this.isRendering = false;
483→    },
484→
485→    async renderAllPages(fileId) {
486→      this.renderPage(fileId, this.currentPage[fileId]);
487→    },
488→
489→    zoomIn() {
490→      const newScale = this.currentScale + 0.2;
491→      this.renderPage(this.currentDocumentIndex, this.currentPage[this.currentDocumentIndex], newScale);
492→    },
493→
494→    zoomOut() {
495→      const newScale = this.currentScale - 0.2;
496→      if (newScale > 0.1) {
497→        this.renderPage(this.currentDocumentIndex, this.currentPage[this.currentDocumentIndex], newScale);
498→      }
499→    },
500→
501→    prevPage() {
502→      const fileId = this.currentDocumentIndex;
503→      if (this.currentPage[fileId] > 1 && !this.isRendering) {
504→
505→        this.currentPage[fileId] = this.currentPage[fileId] - 1; 
506→        this.renderPage(fileId, this.currentPage[fileId]);
507→      }
508→    },
509→
510→    nextPage() {
511→      const fileId = this.currentDocumentIndex;
512→      if (this.currentPage[fileId] < this.pdfPages[fileId].length && !this.isRendering) {
513→        this.currentPage[fileId] = this.currentPage[fileId] + 1; 
514→        this.renderPage(fileId, this.currentPage[fileId]);
515→      }
516→    },
517→
518→    addSignatureField(fileId) {
519→      const currentPageNumber = this.currentPage[fileId];
520→
521→      if (!this.signatureCounters[fileId]) {
522→        this.signatureCounters[fileId] = 1;
523→      }
524→
525→      let availableId = this.availableIdsPerDoc[fileId] && this.availableIdsPerDoc[fileId].length > 0
526→        ? this.availableIdsPerDoc[fileId].shift()  
527→        : this.signatureCounters[fileId]++;  
528→
529→      const uniqueId = `${fileId}-${uuidv4()}`;
530→
531→      const newField = {
532→        id: uniqueId,
533→        instanceId: uniqueId,
534→        name: `[$FIRMA${availableId}]`,
535→        type: 'signature',
536→        top: 20,
537→        left: 50,
538→        width: 200,
539→        height: 100,
540→        pageNumber: currentPageNumber,
541→        fileId: fileId,
542→        includeFullName: true,
543→        includeDocumentInfo: true,
544→      };
545→
546→      this.fields.push(newField);
547→      this.$emit('update-fields', this.fields, fileId);
548→    },
549→
550→    addQrField(fileId) {
551→      if (this.hasQrField) return;
552→
553→      const currentPageNumber = this.currentPage[fileId];
554→      const uniqueId = `${fileId}-${uuidv4()}`;
555→
556→      const newField = {
557→        id: uniqueId,
558→        instanceId: uniqueId,
559→        name: 'Código QR',
560→        type: 'qr',
561→        top: 50,
562→        left: 50,
563→        width: 100,
564→        height: 100,
565→        pageNumber: currentPageNumber,
566→        fileId: fileId,
567→      };
568→
569→      this.fields.push(newField);
570→      this.$emit('update-fields', this.fields, fileId);
571→    },
572→
573→    openSignerDataDialog(field) {
574→      this.editingField = field; 
575→      this.signerDataDialog = true; 
576→    },
577→
578→    closeSignerDataDialog() {
579→      this.signerDataDialog = false;
580→      setTimeout(() => {
581→        this.editingField = null; 
582→      }, 300);
583→    },
584→
585→    deleteField(instanceId) {
586→      const fieldToRemove = this.fields.find(field => field.instanceId === instanceId);
587→
588→      if (fieldToRemove) {
589→        const fileId = fieldToRemove.fileId;
590→
591→        if (fieldToRemove.type === 'signature') {
592→          if (!this.availableIdsPerDoc[fileId]) {
593→            this.availableIdsPerDoc[fileId] = [];
594→          }
595→
596→          const fieldNumber = parseInt(fieldToRemove.name.match(/\d+/)?.[0], 10);
597→          if (!isNaN(fieldNumber)) {
598→            this.availableIdsPerDoc[fileId].push(fieldNumber);
599→            this.availableIdsPerDoc[fileId].sort((a, b) => a - b);
600→          }
601→        }
602→
603→        this.fields = this.fields.filter(field => field.instanceId !== instanceId);
604→      }
605→    },
606→
607→    openDuplicateDialog(field) {
608→      this.selectedFieldToDuplicate = field;
609→      this.selectedDuplicatePage = this.currentPage[this.currentDocumentIndex];
610→      this.showDuplicateDialog = true;
611→    },
612→
613→    confirmDuplicateField() {
614→      if (!this.selectedFieldToDuplicate || !this.selectedDuplicatePage) return;
615→
616→      const original = this.selectedFieldToDuplicate;
617→      const newField = {
618→        ...original,
619→        id: `${original.fileId}-${uuidv4()}`,
620→        instanceId: `${original.fileId}-${uuidv4()}`,
621→        pageNumber: this.selectedDuplicatePage,
622→        top: original.top + 0.05, 
623→        left: original.left + 0.05,
624→      };
625→
626→      newField.top = Math.min(newField.top, 0.9);
627→      newField.left = Math.min(newField.left, 0.9);
628→
629→      this.fields.push(newField);
630→      this.showDuplicateDialog = false;
631→    },
632→
633→
634→    checkCollision(rect1, rect2) {
635→      return (
636→        rect1.left < rect2.left + rect2.width &&
637→        rect1.left + rect1.width > rect2.left &&
638→        rect1.top < rect2.top + rect2.height &&
639→        rect1.top + rect1.height > rect2.top
640→      );
641→    },
642→
643→    startDrag(event, field) {
644→      event.preventDefault();
645→
646→      this.draggingField = field;
647→
648→      const wrapperRect = this.$refs.pdfContainer.querySelector('.pdf-wrapper').getBoundingClientRect();
649→      this.offsetX = event.clientX - (field.left * this.currentScale + wrapperRect.left);
650→      this.offsetY = event.clientY - (field.top * this.currentScale + wrapperRect.top);
651→
652→      this.boundOnDrag = (e) => this.onDrag(e);
653→      this.boundStopDrag = () => this.stopDrag();
654→
655→      document.addEventListener('mousemove', this.boundOnDrag);
656→      document.addEventListener('mouseup', this.boundStopDrag);
657→    },
658→
659→    onDrag(event) {
660→      if (!this.draggingField) return;
661→
662→      event.preventDefault();
663→
664→      const wrapperRect = this.$refs.pdfContainer.querySelector('.pdf-wrapper').getBoundingClientRect();
665→      let newLeft = (event.clientX - this.offsetX - wrapperRect.left) / this.currentScale;
666→      let newTop = (event.clientY - this.offsetY - wrapperRect.top) / this.currentScale;
667→
668→      const maxLeft = this.originalPdfWidth - this.draggingField.width;
669→      const maxTop = this.originalPdfHeight - this.draggingField.height;
670→
671→      newLeft = Math.max(0, Math.min(newLeft, maxLeft));
672→      newTop = Math.max(0, Math.min(newTop, maxTop));
673→
674→      const potentialRect = {
675→        left: newLeft,
676→        top: newTop,
677→        width: this.draggingField.width,
678→        height: this.draggingField.height
679→      };
680→
681→      const hasCollision = this.filteredFields.some(field => {
682→        if (field.instanceId === this.draggingField.instanceId) return false;
683→        return this.checkCollision(potentialRect, field);
684→      });
685→
686→      if (!hasCollision) {
687→        this.draggingField.left = newLeft;
688→        this.draggingField.top = newTop;
689→      }
690→    },
691→
692→    stopDrag() {
693→      document.removeEventListener('mousemove', this.boundOnDrag);
694→      document.removeEventListener('mouseup', this.boundStopDrag);
695→
696→      this.boundOnDrag = null;
697→      this.boundStopDrag = null;
698→      
699→      this.draggingField = null;
700→    },
701→
702→    startResize(event, field) {
703→      event.stopPropagation();
704→      this.resizingField = field;
705→      document.addEventListener('mousemove', this.onResize);
706→      document.addEventListener('mouseup', this.stopResize);
707→    },
708→
709→    onResize(event) {
710→      if (!this.resizingField) return;
711→
712→      const canvasRect = this.$refs.pdfCanvas.getBoundingClientRect();
713→      const scaleX = canvasRect.width / this.originalPdfWidth;
714→      const scaleY = canvasRect.height / this.originalPdfHeight;
715→
716→      let newWidth = ((event.clientX - canvasRect.left) / scaleX) - this.resizingField.left;
717→      let newHeight = ((event.clientY - canvasRect.top) / scaleY) - this.resizingField.top;
718→
719→      let minWidth, minHeight, maxWidth, maxHeight;
720→
721→      if (this.resizingField.type === 'qr') {
722→        minWidth = 50;
723→        minHeight = 50;
724→        maxWidth = 150;
725→        maxHeight = 150;
726→      } else {
727→        const hasData = this.resizingField.includeFullName || this.resizingField.includeDocumentInfo;
728→        minWidth = hasData ? 150 : 110;
729→        minHeight = hasData ? 100 : 30;
730→        maxWidth = 250;
731→        maxHeight = 180;
732→      }
733→
734→      newWidth = Math.max(minWidth, Math.min(newWidth, maxWidth));
735→      newHeight = Math.max(minHeight, Math.min(newHeight, maxHeight));
736→
737→      const potentialRect = {
738→        left: this.resizingField.left,
739→        top: this.resizingField.top,
740→        width: newWidth,
741→        height: newHeight
742→      };
743→
744→      const hasCollision = this.filteredFields.some(field => {
745→        if (field.instanceId === this.resizingField.instanceId) return false;
746→        return this.checkCollision(potentialRect, field);
747→      });
748→
749→      if (!hasCollision) {
750→        this.resizingField.width = newWidth;
751→        this.resizingField.height = newHeight;
752→      }
753→    },
754→
755→    stopResize() {
756→      document.removeEventListener('mousemove', this.onResize);
757→      document.removeEventListener('mouseup', this.stopResize);
758→      this.resizingField = null;
759→    },
760→
761→    enforceMinDataSize() {
762→      if (!this.editingField) return;
763→
764→      const minWidthWithData = 150; 
765→      const minHeightWithData = 100;
766→
767→      this.editingField.width = Math.max(this.editingField.width, minWidthWithData);
768→      this.editingField.height = Math.max(this.editingField.height, minHeightWithData);
769→    },
770→
771→    onScroll() {
772→      this.scrollX = this.$refs.pdfContainer.scrollLeft;
773→      this.scrollY = this.$refs.pdfContainer.scrollTop;
774→    },
775→
776→    prevDocument() {
777→      if (this.currentDocumentIndex > 0) {
778→        this.currentDocumentIndex--;
779→        this.clearCanvas();
780→        this.$nextTick(() => this.renderAllPages(this.currentDocumentIndex));
781→      }
782→    },
783→
784→    nextDocument() {
785→      if (this.currentDocumentIndex < this.pdfs.length - 1) {
786→        this.currentDocumentIndex++;
787→        this.clearCanvas();
788→        this.$nextTick(() => this.renderAllPages(this.currentDocumentIndex));
789→
790→        if (!this.signatureCounters[this.currentDocumentIndex]) {
791→          this.signatureCounters[this.currentDocumentIndex] = 1;
792→        }
793→      }
794→    },
795→
796→    clearCanvas() {
797→      const pageNum = this.currentPage[this.currentDocumentIndex];
798→      const canvasRef = 'pdfCanvas' + pageNum;
799→      const canvas = this.$refs[canvasRef]?.[0];
800→      if (canvas) {
801→        const ctx = canvas.getContext("2d");
802→        ctx.clearRect(0, 0, canvas.width, canvas.height);
803→      }
804→    },
805→
806→    selectField(field) {
807→      this.selectedField = field;
808→    },
809→
810→
811→  },
812→};
813→</script>
