    const fileId = fieldToRemove.fileId;

    if (fieldToRemove.type === 'signature') {
      if (!this.availableIdsPerDoc[fileId]) {
        this.availableIdsPerDoc[fileId] = [];
      }

      const fieldNumber = parseInt(fieldToRemove.name.match(/\d+/)?.[0], 10);
