      }
    }

    this.fields = this.fields.filter(field => field.instanceId !== instanceId);
  }
},

openDuplicateDialog(field) {
  this.selectedFieldToDuplicate = field;
  this.selectedDuplicatePage = this.currentPage[this.currentDocumentIndex];
  this.showDuplicateDialog = true;
},

confirmDuplicateField() {
  if (!this.selectedFieldToDuplicate || !this.selectedDuplicatePage) return;

  const original = this.selectedFieldToDuplicate;
  const newField = {
    ...original,
    id: `${original.fileId}-${uuidv4()}`,
    instanceId: `${original.fileId}-${uuidv4()}`,
    pageNumber: this.selectedDuplicatePage,
    top: original.top + 0.05, 
    left: original.left + 0.05,
  };

  newField.top = Math.min(newField.top, 0.9);
  newField.left = Math.min(newField.left, 0.9);

  this.fields.push(newField);
  this.showDuplicateDialog = false;
},


checkCollision(rect1, rect2) {
  return (
