combineDateTime() {
    const endDate = this.endDateTime;
    const endTime = this.time;

    if (endDate && endTime) {
        const formattedDate = moment(endDate).format("YYYY-MM-DD");
        const combinedDateTime = moment(`${formattedDate} ${endTime}`, "YYYY-MM-DD HH:mm");

        if (combinedDateTime.isValid()) {
            this.tempDateTime = combinedDateTime.format("YYYY-MM-DD HH:mm:ss"); 
        } else {
            this.tempDateTime = "";
        }
    } else {
        this.tempDateTime = "";
    }
},

validateEndDateTime(value) {
    if (!value) return 'Fecha y hora de fin requeridas';
    if (moment(value).isBefore(this.startDateTime)) {
        return 'La fecha de fin no puede ser anterior a la de inicio';
    }
    return true;
},

